<script lang="ts">
 import type{Project,Surface,SiteType}from '../model';
 import {nowId}from '../model';
 import {num,areaStats,polygonAreaUTM}from '../engine/calculate';
 export let project:Project;export let update:(p:Partial<Project>)=>void;
 const kinds:{value:SiteType;label:string}[]=[{value:'roof',label:'پشت‌بام مسطح'},{value:'shed',label:'سقف سوله'},{value:'ground',label:'سطح زمین'}];
 function edit(id:string,field:keyof Surface,value:string|number){update({surfaces:project.surfaces.map(s=>s.id===id?{...s,[field]:value}:s)});}
 function add(){update({surfaces:[...project.surfaces,{id:nowId(),name:`سطح ${project.surfaces.length+1}`,type:'roof',lengthM:10,widthM:10,tiltDeg:0,azimuthDeg:180,usablePct:75}]});}
 const n=(e:Event)=>Number((e.currentTarget as HTMLInputElement).value);
 $: areas=areaStats(project);
 $: utmArea=polygonAreaUTM(project.utmPolygon);
</script>
<section class="stage-heading"><h1>فضای احداث و موقعیت پروژه</h1><p>سطوح قابل نصب را معرفی کنید؛ نقشه فعلی شماتیک است و جایگزین نقشه ماهواره‌ای نیست.</p></section>
<div class="layout-two site-main">
 <div class="panel map-panel"><div class="panel-head"><h2>پیش‌نمایش محدوده</h2><span class="chip">نمای شماتیک، فاقد داده ماهواره‌ای</span></div>
  <div class="site-map" role="img" aria-label="طرح شماتیک سطح نصب پنل خورشیدی"><div class="map-grid"></div><svg viewBox="0 0 700 360" preserveAspectRatio="xMidYMid meet"><polygon points="130,94 510,64 596,249 189,296" fill="#fedc73" fill-opacity=".28" stroke="#efb900" stroke-width="5"/>{#each [[130,94],[510,64],[596,249],[189,296]] as pt}<circle cx={pt[0]} cy={pt[1]} r="7" fill="#f4bb17" stroke="white" stroke-width="3"/>{/each}<g fill="#2e70a4" opacity=".93">{#each Array(8) as _,r}{#each Array(12) as _,c}<rect x={208+c*26+r*2} y={125+r*16} width="22" height="12" rx="1" stroke="white" stroke-width="0.8"/>{/each}{/each}</g><g fill="#123957" font-size="15"><text x="355" y="44" text-anchor="middle">N ↑</text><text x="350" y="345" text-anchor="middle">محدوده انتخابی (شماتیک)</text></g></svg></div>
  <div class="inline-stats"><div><span>مساحت ناخالص</span><strong class="Fa-Num">{num(areas.gross,2)} m²</strong></div><div><span>مساحت قابل استفاده</span><strong class="Fa-Num">{num(areas.usable,2)} m²</strong></div><div><span>تعداد سطوح</span><strong class="Fa-Num">{num(project.surfaces.length)}</strong></div></div>
  <div class="hint">برای جانمایی دقیق، باید در فاز بعد نقشه واقعی، موانع و راهروهای دسترسی به مدل هندسی متصل شوند.</div>
 </div>
 <div class="stack"><div class="panel"><div class="panel-head"><h2>مشخصات محل نصب</h2><button class="btn btn-outline btn-small" type="button" onclick={add}>+ افزودن سطح</button></div>
 {#each project.surfaces as s,i (s.id)}<div class="surface-form"><div class="surface-head"><strong>سطح {num(i+1)} — {s.name}</strong><button type="button" disabled={project.surfaces.length===1} onclick={()=>update({surfaces:project.surfaces.filter(x=>x.id!==s.id)})} class="text-danger">حذف</button></div>
 <div class="form-grid"><label>نوع محل نصب<select value={s.type} onchange={e=>edit(s.id,'type',e.currentTarget.value)}>{#each kinds as k}<option value={k.value}>{k.label}</option>{/each}</select></label><label>جهت سطح (آزیموت)<input type="number" min="0" max="359" step="1" value={s.azimuthDeg} oninput={e=>edit(s.id,'azimuthDeg',n(e))}/></label><label>طول (m)<input type="number" min="0" step="0.1" value={s.lengthM} oninput={e=>edit(s.id,'lengthM',n(e))}/></label><label>عرض (m)<input type="number" min="0" step="0.1" value={s.widthM} oninput={e=>edit(s.id,'widthM',n(e))}/></label><label>فضای مفید (%)<input type="number" min="0" max="100" step="1" value={s.usablePct} oninput={e=>edit(s.id,'usablePct',n(e))}/></label><label class:disabled={s.type==='roof'}>شیب (درجه)<div class="slope-input"><input type="range" min="0" max="60" step="0.5" disabled={s.type==='roof'} value={s.type==='roof'?0:s.tiltDeg} oninput={e=>edit(s.id,'tiltDeg',n(e))}/><input class="small-number" type="number" min="0" max="60" step="0.5" disabled={s.type==='roof'} value={s.type==='roof'?0:s.tiltDeg} oninput={e=>edit(s.id,'tiltDeg',n(e))}/></div></label></div></div>{/each}</div>
 <div class="panel"><div class="panel-head"><h2>مختصات موقعیت</h2><span class="chip">ورود دستی</span></div><div class="form-grid"><label>عرض جغرافیایی (Lat)<input type="number" step="0.000001" value={project.latitude??''} oninput={e=>update({latitude:e.currentTarget.value===''?null:n(e)})}/></label><label>طول جغرافیایی (Lon)<input type="number" step="0.000001" value={project.longitude??''} oninput={e=>update({longitude:e.currentTarget.value===''?null:n(e)})}/></label><label>ارتفاع از سطح دریا (m)<input type="number" step="0.1" value={project.elevationM??''} oninput={e=>update({elevationM:e.currentTarget.value===''?null:n(e)})}/></label><label>UTM Zone<input value={project.utmZone} oninput={e=>update({utmZone:e.currentTarget.value})}/></label></div><label>رئوس چندضلعی UTM — هر خط Easting, Northing<textarea rows="3" placeholder="500000, 3950000" value={project.utmPolygon} oninput={e=>update({utmPolygon:e.currentTarget.value})}></textarea></label><div class="hint">{#if utmArea!==null}مساحت محاسبه‌شده چندضلعی: <b>{num(utmArea,2)} m²</b>{:else}برای محاسبه مساحت UTM حداقل سه رأس معتبر وارد کنید.{/if} این محاسبه مستقل از مساحت ابعادی است.</div></div>
 {#if project.system!=='grid'}<div class="panel"><div class="panel-head"><h2>مصرف و ذخیره‌سازی</h2></div><div class="form-grid"><label>بار ضروری (kW)<input type="number" min="0" step="0.1" value={project.load.criticalKw} oninput={e=>update({load:{...project.load,criticalKw:n(e)}})}/></label><label>مدت پشتیبانی (ساعت)<input type="number" min="0" step="0.5" value={project.load.backupHours} oninput={e=>update({load:{...project.load,backupHours:n(e)}})}/></label><label>مصرف روزانه (kWh)<input type="number" min="0" value={project.load.dailyConsumptionKwh} oninput={e=>update({load:{...project.load,dailyConsumptionKwh:n(e)}})}/></label><label>سهم خودمصرفی (%)<input type="number" min="0" max="100" value={project.load.selfUsePct} oninput={e=>update({load:{...project.load,selfUsePct:n(e)}})}/></label></div></div>{:else}<div class="panel disabled-panel"><h2>مصرف و ذخیره‌سازی</h2><p>در حالت متصل به شبکه، بخش باتری و مصرف اضطراری غیرفعال است. تنظیمات قبلی محفوظ می‌مانند.</p></div>{/if}
 </div>
</div>

